async function showJob(id){S.job=id;clearInterval(S.poll);const poll=async()=>{try{const d=await api('/api/job?id='+encodeURIComponent(id));const j=d.job,active=['QUEUED','RUNNING','CANCELLING'].includes(j.status),waiting=Boolean(j.awaiting_input);$('#consoleStatus').textContent=`${j.action} · ${j.status}${j.interactive?' · avaliação humana':''}`;$('#console').textContent=j.tail||j.command_display;$('#console').scrollTop=$('#console').scrollHeight;$('#cancelJobBtn').style.display=active?'inline-block':'none';$('#cancelJobBtn').disabled=j.status==='CANCELLING';$('#jobInput').classList.toggle('hidden',!waiting);const inputLabel=$('#jobInput span');if(inputLabel)inputLabel.textContent=waiting?(j.input_prompt?`Avaliação solicitada: ${j.input_prompt}`:'O validator está aguardando sua avaliação:'):'O validator está aguardando sua avaliação:';if(['PASS','FAIL','ERROR','CANCELLED'].includes(j.status)){clearInterval(S.poll);$('#jobInput').classList.add('hidden');if(S.selected&&['upscale_texture','publish_enhancement','restore_enhancement'].includes(j.action)){try{await selectAsset(S.selected)}catch(e){}}}}catch(e){}};await poll();S.poll=setInterval(poll,700)}
