function entityCountsText(e){const rc=e.role_counts||{};return [e.model_paths?.length?`${e.model_paths.length} model`:null,e.texture_paths?.length?`${e.texture_paths.length} tex`:null,e.config_paths?.length?`${e.config_paths.length} config`:null,e.animation_paths?.length?`${e.animation_paths.length} anim`:null,e.icon_paths?.length?`${e.icon_paths.length} icon`:null,e.audio_paths?.length?`${e.audio_paths.length} áudio`:null,e.registry_asset_count?`${e.registry_asset_count} registry`:null].filter(Boolean).join(' · ')}
