function renderEntityDetail(d){const e=d.entity;if(!e)return;const tag={CHARACTER:'CHAR',ITEM:'ITEM',MONSTER:'MON',NPC:'NPC',EFFECT:'FX',MAP_FIELD:'MAP'}[e.semantic_group]||e.semantic_group;const preview=e.representative_preview?`<img src="/api/preview?path=${encodeURIComponent(e.representative_preview)}" data-preview-fallback="icon" data-ext="${esc(tag)}">`:`<span class=ext-icon>${esc(tag)}</span>`;const fam=Object.entries(e.registry_family_counts||{}).map(([k,v])=>`${k} (${v})`).join(', ')||'—';const bind=Object.entries(e.registry_binding_mode_counts||{}).map(([k,v])=>`${k} (${v})`).join(', ')||'—';const paths=(e.all_paths||[]).slice(0,80).map(x=>`<div class=entity-model-row><code>${esc(x)}</code></div>`).join('')||'<div class=micro>Nenhum path relacionado.</div>';const relations=(e.relationships||[]).slice(0,80).map(x=>`<div class=entity-model-row><b>${esc(x.type||'RELATION')}</b><small>${esc(x.from||'')} → ${esc(x.to||'')}</small><small>${esc(x.evidence||'')}</small></div>`).join('');$('#entityDetail').innerHTML=`<div class=entity-detail-grid><div><div class=entity-detail-preview>${preview}</div><div style="margin-top:10px"><button class="btn primary" id=openEntityAssets>Ver assets relacionados no Catálogo</button></div></div><div><h2 style="margin-top:0">${esc(e.display_name)}</h2><div class=entity-detail-meta><b>Grupo</b><span>${esc(e.semantic_group)}</span><b>Identidade</b><span>${esc(e.identity_evidence||'—')}</span><b>Raiz/contexto</b><span>${esc(e.folder_root||'—')}</span><b>Assets relacionados</b><span>${Number(e.asset_count||0).toLocaleString()}</span><b>Registry</b><span>${Number(e.registry_asset_count||0).toLocaleString()} assets</span><b>Famílias</b><span>${esc(fam)}</span><b>Bindings</b><span>${esc(bind)}</span><b>Runtime</b><span>${esc(e.runtime_status)}</span><b>Writer</b><span>${esc(e.writer_status)}</span></div>${relations?`<div class=entity-path-list><h3>Relações verificadas</h3>${relations}</div>`:''}<div class=entity-path-list><h3>Assets agrupados</h3>${paths}</div></div></div>`;bindPreviewFallbacks($('#entityDetail'));$('#openEntityAssets').onclick=()=>openEntityAssets(e.entity_key,e.semantic_group)}
