async function loadGeneralCensus(){if(!$('#generalCensusRows'))return;const side=$('#generalCensusSide')?.value||'',decision=$('#generalCensusDecision')?.value||'',family=$('#generalCensusFamily')?.value||'',q=$('#generalCensusSearch')?.value.trim()||'';try{const qs=new URLSearchParams({side,decision,family,q,limit:'300'});const d=await api('/api/general-census?'+qs);const summary=d.summary||{};setCountOptions($('#generalCensusDecision'),summary.decision_counts||{},'Todas as decisões');setCountOptions($('#generalCensusFamily'),summary.physical_family_counts||{},'Todas as famílias');const freshness=d.freshness?` · ${d.freshness}`:'';$('#generalCensusCount').textContent=d.status==='NOT_RUN'?'Sem relatório. Execute Censo geral (plan-only).':`${Number(d.filtered_rows||0).toLocaleString()} de ${Number(d.total_rows||0).toLocaleString()} candidatos${freshness}`;const rows=d.rows||[];$('#generalCensusRows').innerHTML=rows.length?rows.map(row=>{const baseEv=row.reachability_evidence||row.review_evidence||row.manifest_evidence||row.source_evidence||row.reason||'—';const bundle=row.recovery_bundle_status?`Bundle ${row.recovery_bundle_status} · members ${row.recovery_bundle_member_count||0} · missing ${row.recovery_bundle_missing_count||0} · review ${row.recovery_bundle_review_count||0}`:'';const ev=bundle?`${bundle} · ${baseEv}`:baseEv;const strong=String(row.required_by_reachable_root).toLowerCase()==='true';return `<tr><td><span class="status-chip ${strong?'pass':'review'}">${esc(row.decision||'REVIEW')}</span></td><td>${esc(row.side||'—')}</td><td>${esc(row.physical_family||'—')}</td><td class=path title="${esc(row.path||'')}">${esc(row.path||'—')}</td><td title="${esc(ev)}">${esc(String(ev).slice(0,220))}</td></tr>`}).join(''):'<tr><td colspan="5" class="empty">Nenhum candidato corresponde aos filtros atuais.</td></tr>'}catch(e){$('#generalCensusRows').innerHTML=`<tr><td colspan="5" class="empty">${esc(e.message)}</td></tr>`;$('#generalCensusCount').textContent='Erro ao carregar censo geral'}}
function compactCounts(counts,max=8){const rows=Object.entries(counts||{}).sort((a,b)=>Number(b[1])-Number(a[1])).slice(0,max);return rows.length?rows.map(([k,v])=>`${k} ${Number(v).toLocaleString()}`).join(' · '):'—'}
